/* The group squares the joins between its buttons; the outer corners keep
   the buttons' own radius. A 1px overlap lets neighbouring edges share one
   hairline. Two class selectors outrank a button's own radius rule. */
.group {
  display: inline-flex;
  isolation: isolate;
}

.vertical {
  flex-direction: column;
}

.group > * {
  position: relative;
}

/* Focus or hover lifts a button over its neighbours, so its ring is whole. */
.group > *:hover,
.group > *:focus-visible {
  z-index: 1;
}

.horizontal > *:not(:last-child) {
  border-top-right-radius: var(--button-group-join, 0);
  border-bottom-right-radius: var(--button-group-join, 0);
}

.horizontal > *:not(:first-child) {
  margin-left: -1px;
  border-top-left-radius: var(--button-group-join, 0);
  border-bottom-left-radius: var(--button-group-join, 0);
}

.vertical > *:not(:last-child) {
  border-bottom-left-radius: var(--button-group-join, 0);
  border-bottom-right-radius: var(--button-group-join, 0);
}

.vertical > *:not(:first-child) {
  margin-top: -1px;
  border-top-left-radius: var(--button-group-join, 0);
  border-top-right-radius: var(--button-group-join, 0);
}

.vertical > * {
  justify-content: flex-start;
}

import type { HTMLAttributes, ReactNode } from "react";
import { cx } from "../_internal/cx";
import styles from "./ButtonGroup.module.css";

export type ButtonGroupProps = HTMLAttributes<HTMLDivElement> & {
  children: ReactNode;
  /** Names the group for assistive tech: "Text alignment", "Pagination". Required in practice. */
  "aria-label"?: string;
  /** horizontal (default) joins left to right; vertical stacks top to bottom. */
  orientation?: "horizontal" | "vertical";
};

/**
 * Joins Buttons and IconButtons into one segmented control: shared outer
 * corners, square inner joins and a hairline between neighbours. The
 * buttons keep their own variants and states; the group only shapes them.
 */
export function ButtonGroup({ children, orientation = "horizontal", className, ...rest }: ButtonGroupProps) {
  return (
    <div data-slot="button-group" role="group" aria-orientation={orientation} className={cx(styles.group, styles[orientation], className)} {...rest}>
      {children}
    </div>
  );
}
